package com.bookeasy.file;

import java.io.IOException;
import java.io.InputStream;

/**
 * Where file bytes live. Keys are generated by {@link FileService} and never contain user input.
 * Local disk today (Render persistent disk); an S3-compatible implementation can replace it without
 * touching callers.
 */
public interface FileStorage {

    /** Stores the stream under {@code key}; fails if the key already exists. */
    void store(String key, InputStream content) throws IOException;

    InputStream open(String key) throws IOException;

    /** Removes the object; a missing key is not an error. */
    void delete(String key) throws IOException;

    boolean exists(String key);
}
